\item[S2] L\'aszl\'o Babai, \emph{Graph Isomorphism in Quasipolynomial Time}, Proceedings of STOC 2016, 684--697, abstract and introduction; arXiv:1512.03547. \url{https://arxiv.org/abs/1512.03547}.
\end{description}
